setup:
using WebCommander.Sdk.Client;
using WebCommander.Sdk.Config;

var auth = new AuthConfig(
    baseUrl: Environment.GetEnvironmentVariable("WC_BASE_URL")!,
    clientId: Environment.GetEnvironmentVariable("WC_CLIENT_ID")!,
    clientSecret: Environment.GetEnvironmentVariable("WC_CLIENT_SECRET")!,
    redirectUri: Environment.GetEnvironmentVariable("WC_REDIRECT_URI")!,
    authString: Environment.GetEnvironmentVariable("WC_AUTH_STRING")!,
    clientName: "default");

await using var client = new WebCommanderClient(new SdkConfig(auth, raiseOnError: true));
